public static void removeNegatives(int[] arr) {
    int nextPos = 0; // position to place next non‑negative
    for (int i = 0; i < arr.length; i++) {
        if (arr[i] >= 0) {
            arr[nextPos] = arr[i];
            nextPos++;
        }
    }
    // fill remaining positions with 0
    while (nextPos < arr.length) {
        arr[nextPos] = 0;
        nextPos++;
    }
}

