public static int[] removeDuplicates(int[] arr) {
    int[] temp = new int[arr.length];
    int count = 0;
    for (int i = 0; i < arr.length; i++) {
        boolean duplicate = false;
        for (int j = 0; j < count; j++) {
            if (arr[i] == temp[j]) {
                duplicate = true;
                break;
            }
        }
        if (!duplicate) {
            temp[count] = arr[i];
            count++;
        }
    }
    int[] result = new int[count];
    for (int i = 0; i < count; i++) {
        result[i] = temp[i];
    }
    return result;
}

