import java.io.File;
import java.io.IOException;
import java.util.Scanner;

public static double averageFromFile(String filename) throws IOException {
    Scanner sc = new Scanner(new File(filename));
    int sum = 0;
    int count = 0;
    while (sc.hasNextLine()) {
        String line = sc.nextLine().trim();
        if (line.isEmpty()) {
            continue; // skip empty lines
        }
        // Assume each non-empty line contains a single integer
        int num = Integer.parseInt(line);
        sum += num;
        count++;
    }
    sc.close();
    if (count == 0) {
        return 0.0;
    }
    return (double) sum / count;
}

