public static int countLocalMaxima(int[][] matrix) {
    int count = 0;
    int rows = matrix.length;
    int cols = matrix[0].length;
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            int val = matrix[r][c];
            boolean isMax = true;
            // check up
            if (r > 0 && matrix[r-1][c] >= val) isMax = false;
            // check down
            if (r < rows-1 && matrix[r+1][c] >= val) isMax = false;
            // check left
            if (c > 0 && matrix[r][c-1] >= val) isMax = false;
            // check right
            if (c < cols-1 && matrix[r][c+1] >= val) isMax = false;
            if (isMax) count++;
        }
    }
    return count;
}

